<?php
namespace App\Domain\Documents\Services;
use App\Domain\Documents\Enums\DocumentStatus;use App\Models\Document;use App\Models\DocumentBarcode;use Illuminate\Support\Facades\DB;
class RegisterDocument{public function __construct(private ReferenceAllocator $allocator){}public function execute(array $data,int $userId):Document{return DB::transaction(function()use($data,$userId){$ids=$this->allocator->next((int)now()->format('Y'));$document=Document::create(array_merge($data,['reference_no'=>$ids['reference'],'status'=>DocumentStatus::AwaitingUpload,'registered_by'=>$userId,'registered_at'=>now()]));DocumentBarcode::create(['document_id'=>$document->id,'barcode_value'=>$ids['barcode'],'symbology'=>'CODE128','issued_by'=>$userId,'issued_at'=>now(),'status'=>'ACTIVE']);DB::table('document_status_history')->insert(['document_id'=>$document->id,'from_status'=>null,'to_status'=>DocumentStatus::AwaitingUpload->value,'reason'=>'Initial registration','changed_by'=>$userId,'changed_at'=>now(),'created_at'=>now()]);return $document->load('barcode');},3);}}
